function cabinetLoad(raw){const state={seen:[],stamps:[]};try{const p=JSON.parse(raw||'{}');for(const k of ['seen','stamps'])if(Array.isArray(p[k]))state[k]=[...new Set(p[k].filter(id=>cabinetItems.some(c=>c.id===id)))];}catch{}return state;}
let cabinetState=cabinetLoad(localStorage.getItem('olddays-memory-cabinet')),cabinetSelected='',cabinetZoom=1,cabinetNotice='';
function cabinetAvailable(){return cabinetItems.filter(i=>i.date<=date);}
function cabinetSave(){try{localStorage.setItem('olddays-memory-cabinet',JSON.stringify(cabinetState));}catch{}}
function cabinetOpen(id){if(!cabinetAvailable().some(i=>i.id===id))return false;cabinetSelected=id;cabinetZoom=1;cabinetNotice='';if(!cabinetState.seen.includes(id))cabinetState.seen.push(id);cabinetSave();return true;}
function cabinetAnswer(index){const item=cabinetAvailable().find(i=>i.id===cabinetSelected);if(!item||!Number.isInteger(index)||index<0||index>=item.options.length)return false;if(index!==item.answer){cabinetNotice='再看看照片和卡片上的记录。';return false;}if(!cabinetState.stamps.includes(item.id))cabinetState.stamps.push(item.id);cabinetNotice='✓ 这件旧物，记住了。收藏章已保存在本机。';cabinetSave();return true;}
function cabinetMarkup(){const list=cabinetAvailable(),item=list.find(i=>i.id===cabinetSelected);let body='';if(item){body='<button data-cabinet-back>‹ 收藏夹</button><small>'+item.date+' · 真实照片</small><h3>'+item.title+'</h3><div class="cabinet-photo"><img src="images/references/'+item.file+'" style="width:'+cabinetZoom*100+'%;max-width:none" alt="'+item.title+'，'+item.author+'摄影"></div><nav><button data-cabinet-zoom="1">全图</button><button data-cabinet-zoom="2">放大2倍</button><button data-cabinet-zoom="3">放大3倍</button></nav><p>'+item.text+'</p><details><summary>认一认 · 留一枚收藏章</summary><p>'+item.question+'</p>'+item.options.map((o,i)=>'<button data-cabinet-answer="'+i+'">'+(i+1)+' '+o+'</button>').join('')+'</details><p class="cabinet-credit">'+item.author+' · '+item.license+'<br><a href="'+item.licenseURL+'" target="_blank" rel="noopener">许可</a> · <a href="https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(item.source)+'" target="_blank" rel="noopener">原图与来源</a><br>'+ (item.id==='5230'?'已有裁切版本；依原许可保留署名。':'本页使用原照片，缩放仅用于浏览。')+'</p>';}else{body='<p>把真实旧照片装进手机。看细节、认旧物，留一枚自己的收藏章。</p><div class="cabinet-counter">已翻看 '+cabinetState.seen.length+' / 6 · 收藏章 '+cabinetState.stamps.length+' / 6</div><div class="cabinet-grid">'+list.map(i=>'<button data-cabinet-open="'+i.id+'"><img loading="lazy" src="images/references/'+i.file+'" alt="'+i.title+'"><b>'+i.title+'</b><small>'+i.date+' '+(cabinetState.stamps.includes(i.id)?'✓':'')+'</small></button>').join('')+'</div>'+(!list.length?'<p>当前年代还没有这组照片；2007年开始有记录。可在顶部年代菜单选择2007年或之后。</p>':'')+'<p class="cabinet-credit">只展示所选日期之前的照片。原始照片时间与机型发布时间不同；真实资料不是虚构失主的线索。</p>';}
return '<section class="memory-cabinet"><header><small>MEMORY CARD / 真实旧物</small><h2>口袋旧物志</h2></header>'+(cabinetNotice?'<p role="status">'+cabinetNotice+'</p>':'')+body+'</section>';}
phoneApps.push(['cabinet','口袋旧物志','▧']);systemApps.push({id:'cabinet',name:'口袋旧物志',icon:'▧',color:'brown',desc:'真实照片 · 放大细节 · 认旧物集章'});systemInstalled.push('cabinet');
const cabinetScreenBase=phoneScreen,cabinetAllowedBase=phoneAppAllowed,cabinetShelfBase=phoneGameShelfMarkup;
phoneAppAllowed=function(app){return app==='cabinet'?experienceZone==='phone'&&!isTextOnlyPhone()&&!deviceCapabilities[phoneState.model]:cabinetAllowedBase(app);};
phoneScreen=function(){return phoneState.app==='cabinet'&&phoneAppAllowed('cabinet')?cabinetMarkup():cabinetScreenBase();};
phoneGameShelfMarkup=function(){return '<button class="cabinet-entry" data-phone-app="cabinet"><b>▧ 口袋旧物志</b><span>真实年代照片 · 放大找细节 · 认旧物集章 →</span></button>'+cabinetShelfBase();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-cabinet-open],[data-cabinet-back],[data-cabinet-zoom],[data-cabinet-answer]');if(!b||phoneState.app!=='cabinet')return;e.preventDefault();if(b.dataset.cabinetOpen)cabinetOpen(b.dataset.cabinetOpen);if(b.hasAttribute('data-cabinet-back')){cabinetSelected='';cabinetNotice='';}if(b.dataset.cabinetZoom){cabinetZoom=Math.max(1,Math.min(3,Number(b.dataset.cabinetZoom)||1));}if(b.dataset.cabinetAnswer!==undefined)cabinetAnswer(Number(b.dataset.cabinetAnswer));refreshPhone();});
